import bentoml

@bentoml.service(resources={"cpu": "2"})
class Summarizer:
    def __init__(self):
        from transformers import pipeline
        self.pipe = pipeline("summarization")

    @bentoml.api
    def summarize(self, text: str) -> str:
        return self.pipe(text)[0]["summary_text"]
# serve:  bentoml serve service:Summarizer
